/**
 * @suppress
 */
public object FfiConverterTypeEngine: FfiConverter<Engine, Long> {
    override fun lower(value: Engine): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Engine {
        return Engine(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Engine {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Engine) = 8UL

    override fun write(value: Engine, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



