/**
 * Errors the engine reports across the FFI boundary. Maps one-to-one to the
 * Swift `MLSError` (plan table); `.busy` exists only on the Swift side.
 */
sealed class FfiException: kotlin.Exception() {
    
    class Malformed(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class UnknownGroup(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class NotMember(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Duplicate(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The message belongs to a later epoch than the stored group: a commit was missed.
     */
    class EpochGap(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class PendingCommit(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Storage(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Crypto(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Internal(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Malformed()
            2 -> FfiException.UnknownGroup()
            3 -> FfiException.NotMember()
            4 -> FfiException.Duplicate()
            5 -> FfiException.EpochGap()
            6 -> FfiException.PendingCommit()
            7 -> FfiException.Storage(
                FfiConverterString.read(buf),
                )
            8 -> FfiException.Crypto(
                FfiConverterString.read(buf),
                )
            9 -> FfiException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Malformed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.UnknownGroup -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NotMember -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Duplicate -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.EpochGap -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.PendingCommit -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Malformed -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.UnknownGroup -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.NotMember -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.Duplicate -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.EpochGap -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.PendingCommit -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Storage -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.Crypto -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.Internal -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



