/**
 * @suppress
 */
public object FfiConverterTypeProcessed : FfiConverterRustBuffer<Processed>{
    override fun read(buf: ByteBuffer): Processed {
        return when(buf.getInt()) {
            1 -> Processed.Application(
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterULong.read(buf),
                )
            2 -> Processed.Commit(
                FfiConverterByteArray.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterBoolean.read(buf),
                )
            3 -> Processed.Joined(
                FfiConverterByteArray.read(buf),
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Processed) = when(value) {
        is Processed.Application -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`groupId`)
                + FfiConverterString.allocationSize(value.`sender`)
                + FfiConverterByteArray.allocationSize(value.`plaintext`)
                + FfiConverterULong.allocationSize(value.`epoch`)
            )
        }
        is Processed.Commit -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`groupId`)
                + FfiConverterULong.allocationSize(value.`newEpoch`)
                + FfiConverterBoolean.allocationSize(value.`removedMe`)
            )
        }
        is Processed.Joined -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`groupId`)
                + FfiConverterULong.allocationSize(value.`epoch`)
            )
        }
    }

    override fun write(value: Processed, buf: ByteBuffer) {
        when(value) {
            is Processed.Application -> {
                buf.putInt(1)
                FfiConverterByteArray.write(value.`groupId`, buf)
                FfiConverterString.write(value.`sender`, buf)
                FfiConverterByteArray.write(value.`plaintext`, buf)
                FfiConverterULong.write(value.`epoch`, buf)
                Unit
            }
            is Processed.Commit -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`groupId`, buf)
                FfiConverterULong.write(value.`newEpoch`, buf)
                FfiConverterBoolean.write(value.`removedMe`, buf)
                Unit
            }
            is Processed.Joined -> {
                buf.putInt(3)
                FfiConverterByteArray.write(value.`groupId`, buf)
                FfiConverterULong.write(value.`epoch`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalByteArray: FfiConverterRustBuffer<kotlin.ByteArray?> {
    override fun read(buf: ByteBuffer): kotlin.ByteArray? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterByteArray.read(buf)
    }

    override fun allocationSize(value: kotlin.ByteArray?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterByteArray.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ByteArray?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterByteArray.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}




